insert into public.ob_kb (key, lang, value_text, verified_source, updated_at) values
('kb_01_what_en','en',$$Kring (กริ๊ง!) is a free Bangkok people app for 18+. Make your card, post Reels of real Bangkok places, and meet people. It is not a dating service and not a booking or payment service.$$,'terms.html §1-2',now()),
('kb_01_what_th','th',$$กริ๊ง! เป็นแอปฟรีสำหรับคนในกรุงเทพฯ อายุ 18 ปีขึ้นไป ทำการ์ดของคุณ โพสต์รีลสถานที่จริงในกรุงเทพฯ และรู้จักเพื่อนใหม่ ไม่ใช่แอปหาคู่ และไม่ใช่บริการจองหรือรับชำระเงิน$$,'terms.html §1-2',now()),
('kb_02_face_en','en',$$Face check: a 3-second selfie check in the app. The selfie is deleted within 30 days; Kring keeps only a face code (a list of numbers) to keep one person = one account and pay prizes fairly. Face data is never sold or used for ads. You can ask to delete it via Help or ops@kringapp.com.$$,'terms.html §8 · V5VerifyAws',now()),
('kb_02_face_th','th',$$การยืนยันใบหน้า: ถ่ายเซลฟี่ในแอป ใช้เวลา 3 วินาที เซลฟี่จะถูกลบภายใน 30 วัน กริ๊ง! เก็บไว้แค่รหัสใบหน้า (ชุดตัวเลข) เพื่อให้หนึ่งคนมีหนึ่งบัญชีและจ่ายรางวัลอย่างยุติธรรม ไม่ขายข้อมูลใบหน้าและไม่ใช้ทำโฆษณา ขอให้ลบได้ทางเมนูช่วยเหลือหรือ ops@kringapp.com$$,'terms.html §8 · V5VerifyAws',now()),
('kb_03_unverified_en','en',$$Without a face check you can only watch Reels: no People tab, no chat with members, no posting, no weekly prizes, and daily-task Rings can't be collected. Chat with the Kring Team (Help) always works.$$,'kr8_rings_config face_gate_on · 0175 · 0172',now()),
('kb_03_unverified_th','th',$$ถ้ายังไม่ได้ยืนยันใบหน้า จะดูได้แค่รีล ยังไม่เห็นหน้า People แชทกับสมาชิกไม่ได้ โพสต์ไม่ได้ ไม่มีสิทธิ์รางวัลประจำสัปดาห์ และยังรับริงจากภารกิจรายวันไม่ได้ ส่วนแชทกับทีมกริ๊ง! (ช่วยเหลือ) ใช้ได้เสมอ$$,'kr8_rings_config face_gate_on · 0175 · 0172',now()),
('kb_04_tasks_en','en',$$Daily tasks (face-checked members only), max 6 Rings a day: Open Kring +1 · Answer 1 Ask a Thai question +3 (at least 15 characters) · Quick vote (This or that) +1 · Watch 3 Reels to the end +1. "Say it in Thai" is coming soon. Tasks reset at 00:00 Bangkok time. Task Rings add to your weekly total.$$,'0172_daily_tasks · kr8_rings_config task_* · creator-terms §3',now()),
('kb_04_tasks_th','th',$$ภารกิจรายวัน (เฉพาะสมาชิกที่ยืนยันใบหน้าแล้ว) ได้สูงสุดวันละ 6 ริง: เปิดกริ๊ง! +1 · ตอบ 1 คำถามใน "ถามคนไทย" +3 (อย่างน้อย 15 ตัวอักษร) · โหวตด่วน (อันไหนดี) +1 · ดูรีล 3 อันจนจบ +1 ส่วน "พูดเป็นภาษาไทย" จะมาเร็วๆ นี้ ภารกิจรีเซ็ตทุกวันเวลา 00:00 น. ตามเวลากรุงเทพฯ และริงจากภารกิจนับรวมในคะแนนประจำสัปดาห์$$,'0172_daily_tasks · kr8_rings_config task_* · creator-terms §3',now()),
('kb_05_thisorthat_en','en',$$This or that: one question a day, posted by Kring. You vote once and your vote is locked; the results show after you vote. Voting is the Quick vote task (+1 Ring).$$,'0177_this_or_that · v5Tasks',now()),
('kb_05_thisorthat_th','th',$$อันไหนดี (This or that): วันละ 1 คำถาม ตั้งโดยกริ๊ง! โหวตได้คนละครั้งและเปลี่ยนไม่ได้ ผลโหวตจะขึ้นหลังจากคุณเลือก การโหวตนับเป็นภารกิจโหวตด่วน (+1 ริง)$$,'0177_this_or_that · v5Tasks',now()),
('kb_06_board_en','en',$$Weekly board: Monday 00:00 to Sunday 23:59 Bangkok time; ranks 1-10 are shown. Rings per Reel = likes + 3 × saves + 5 × link opens. A link open counts when someone opens your Reel's link from Instagram or TikTok (max 10 a day per Reel; opens from LINE don't count). Likes and saves from visitors to Bangkok count double. Comments give no Rings. Ties: the earlier first post is ahead.$$,'creator-terms §3 · kr8_rings_config',now()),
('kb_06_board_th','th',$$กระดานประจำสัปดาห์: วันจันทร์ 00:00 ถึงวันอาทิตย์ 23:59 ตามเวลากรุงเทพฯ แสดงอันดับ 1-10 ริงต่อรีล = ไลก์ + 3 × เซฟ + 5 × เปิดลิงก์ การเปิดลิงก์นับเมื่อมีคนเปิดลิงก์รีลของคุณจาก Instagram หรือ TikTok (สูงสุด 10 ครั้งต่อวันต่อรีล การเปิดจาก LINE ไม่นับ) ไลก์และเซฟจากคนที่มาเที่ยวกรุงเทพฯ นับสองเท่า คอมเมนต์ไม่ได้ริง ถ้าคะแนนเท่ากัน คนที่โพสต์รีลแรกก่อนอยู่อันดับสูงกว่า$$,'creator-terms §3 · kr8_rings_config',now()),
('kb_07_bestperday_en','en',$$From Monday 23 Nov 2026: post as many Reels as you like; your best Reel of each Bangkok day counts, so up to 7 Reels a week. (Before 23 Nov only your single best Reel of the week counted.)$$,'creator-terms §3 · kr8_rings_config board_v2_from',now()),
('kb_07_bestperday_th','th',$$ตั้งแต่วันจันทร์ที่ 23 พ.ย. 2569: โพสต์รีลได้ไม่จำกัด นับรีลที่ได้ริงมากที่สุดของแต่ละวัน วันละ 1 รีล รวมสูงสุด 7 รีลต่อสัปดาห์ (ก่อนวันที่ 23 พ.ย. นับแค่รีลที่ดีที่สุด 1 รีลต่อสัปดาห์)$$,'creator-terms §3 · kr8_rings_config board_v2_from',now()),
('kb_08_fairplay_en','en',$$Fair play: likes and saves from face-checked members count once per person per Reel, never your own and never from a linked account (same face or device). The same person counts in full on 3 of your Reels a week, then half. Likes from members without a face check: 1 Ring per person per Reel, at most 2 such Rings a day for you in total (their saves and link opens add nothing; accounts under 24 hours old don't count). Re-uploading your own clip earns nothing. One person, one account: vote rings, bought views, copied clips or many accounts mean removal from rewards. You can ask for a score re-check within 3 days.$$,'creator-terms §4, §11',now()),
('kb_08_fairplay_th','th',$$เล่นอย่างแฟร์: ไลก์และเซฟจากสมาชิกที่ยืนยันใบหน้าแล้ว หนึ่งคนนับหนึ่งครั้งต่อรีล ไม่นับของตัวเอง และไม่นับจากบัญชีที่เชื่อมกัน (หน้าเดียวกันหรือเครื่องเดียวกัน) คนเดิมนับเต็มใน 3 รีลของคุณต่อสัปดาห์ หลังจากนั้นนับครึ่ง ไลก์จากสมาชิกที่ยังไม่ยืนยันใบหน้า: 1 ริงต่อคนต่อรีล รวมไม่เกินวันละ 2 ริงต่อคุณ (เซฟและการเปิดลิงก์ของเขาไม่ได้ริง บัญชีที่อายุไม่ถึง 24 ชั่วโมงไม่นับ) อัปโหลดคลิปเดิมซ้ำไม่ได้ริง หนึ่งคนหนึ่งบัญชี การปั่นยอด ซื้อวิว ก๊อปคลิป หรือใช้หลายบัญชี จะถูกตัดสิทธิ์รางวัล ขอตรวจคะแนนใหม่ได้ภายใน 3 วัน$$,'creator-terms §4, §11',now()),
('kb_09_invite_en','en',$$Invites: when a friend who joined with your invite link passes the face check or gets a first Reel approved, you both get 10 Rings (a daily limit applies).$$,'creator-terms §3 · kr8_rings_config invite',now()),
('kb_09_invite_th','th',$$ชวนเพื่อน: เมื่อเพื่อนที่สมัครผ่านลิงก์ชวนของคุณยืนยันใบหน้า หรือรีลแรกผ่านการตรวจ คุณและเพื่อนได้คนละ 10 ริง (มีจำกัดต่อวัน)$$,'creator-terms §3 · kr8_rings_config invite',now()),
('kb_10_prizes_en','en',$$Weekly prizes: #1 ฿1,500 · #2 ฿900 · #3 ฿600 · #4 ฿500 · #5 ฿400 · #6 ฿250 · #7 ฿150 · #8 ฿100. Ranks 9 and 10 are on the board with no prize. A prize rank needs at least 25 Rings. One person holds one rank. There are no daily prizes. After the week closes there is a results check of up to 24 hours before prizes open in Rewards.$$,'creator-terms §5 · terms §5 · kr8_rings_config prize_*',now()),
('kb_10_prizes_th','th',$$รางวัลประจำสัปดาห์: อันดับ 1 ฿1,500 · อันดับ 2 ฿900 · อันดับ 3 ฿600 · อันดับ 4 ฿500 · อันดับ 5 ฿400 · อันดับ 6 ฿250 · อันดับ 7 ฿150 · อันดับ 8 ฿100 อันดับ 9 และ 10 ติดกระดานแต่ไม่มีรางวัล อันดับที่ได้รางวัลต้องมีอย่างน้อย 25 ริง หนึ่งคนได้หนึ่งอันดับ ไม่มีรางวัลรายวัน หลังปิดสัปดาห์จะมีการตรวจผลไม่เกิน 24 ชั่วโมงก่อนเปิดให้รับในหน้ารางวัล$$,'creator-terms §5 · terms §5 · kr8_rings_config prize_*',now()),
('kb_11_claim_en','en',$$Claiming a prize needs a passed face check. Open Rewards, tap Claim and choose one: Grab at full value, or TrueMoney at 75% (TrueMoney keeps 25%; the claim screen shows the exact amount). Each prize is claimed once and you get a code on your phone. Prizes are not exchanged for cash.$$,'creator-terms §5-6',now()),
('kb_11_claim_th','th',$$การรับรางวัลต้องยืนยันใบหน้าก่อน เปิดหน้ารางวัล กดรับ แล้วเลือก 1 ช่องทาง: Grab ได้เต็มจำนวน หรือ TrueMoney ได้ 75% (TrueMoney หัก 25% หน้ารับรางวัลจะแสดงยอดที่ได้จริง) รางวัลหนึ่งรางวัลกดรับได้ครั้งเดียว และจะได้รับโค้ดบนมือถือ รางวัลแลกเป็นเงินสดไม่ได้$$,'creator-terms §5-6',now()),
('kb_12_keeplive_en','en',$$A winning Reel must stay public on Kring for 14 days. If you delete or hide it earlier, that reward is cancelled.$$,'creator-terms §7',now()),
('kb_12_keeplive_th','th',$$รีลที่ได้รางวัลต้องเปิดเป็นสาธารณะบนกริ๊ง! 14 วัน ถ้าลบหรือซ่อนก่อน รางวัลนั้นจะถูกยกเลิก$$,'creator-terms §7',now()),
('kb_13_founding_en','en',$$Founding Local ฿100 is full and closed: new members can't get it. Everyone can still win the weekly prizes.$$,'creator-terms §5 · terms §5',now()),
('kb_13_founding_th','th',$$Founding Local ฿100 เต็มและปิดแล้ว สมาชิกใหม่จะไม่ได้รับ แต่ทุกคนยังลุ้นรางวัลประจำสัปดาห์ได้$$,'creator-terms §5 · terms §5',now()),
('kb_14_posting_en','en',$$Posting a Reel (needs a face check): tap Film now to use the in-app camera, or pick a clip from your gallery. Vertical video, 5-60 seconds (a longer clip opens a trim step). It must be your own clip of a real Bangkok place, with the place pinned. No copied clips, no alcohol, no politics, no attacks on a named person or shop; AI-edited visuals must be labelled.$$,'creator-terms §2 · V5Camera · reels/trim source',now()),
('kb_14_posting_th','th',$$การโพสต์รีล (ต้องยืนยันใบหน้าก่อน): กด "ถ่ายเลย" เพื่อใช้กล้องในแอป หรือกด "เลือกจากแกลเลอรี" วิดีโอแนวตั้ง ยาว 5-60 วินาที (คลิปที่ยาวกว่านั้นจะมีขั้นตอนตัดคลิปให้) ต้องเป็นคลิปที่คุณถ่ายเองของสถานที่จริงในกรุงเทพฯ และปักหมุดสถานที่ ห้ามก๊อปคลิปคนอื่น ห้ามแอลกอฮอล์ การเมือง หรือโจมตีบุคคลหรือร้านค้า ภาพที่แต่งด้วย AI ต้องระบุ$$,'creator-terms §2 · V5Camera · reels/trim source',now()),
('kb_15_safety_en','en',$$Safety: Kring never asks you to pay, transfer money, or share a password, OTP or card number. Meet in public places only. No paid companionship or asking for money. Report anything suspicious to the Kring Team.$$,'creator-terms §6 · terms §3',now()),
('kb_15_safety_th','th',$$ความปลอดภัย: กริ๊ง! ไม่เคยขอให้คุณจ่ายเงิน โอนเงิน หรือบอกรหัสผ่าน OTP หรือเลขบัตร นัดเจอในที่สาธารณะเท่านั้น ห้ามเสนอหรือขอเป็นเพื่อนเที่ยวแลกเงิน หรือขอเงิน เจออะไรน่าสงสัยแจ้งทีมกริ๊ง! ได้เลย$$,'creator-terms §6 · terms §3',now()),
('kb_16_account_en','en',$$One person, one account. If more than one is found, Kring keeps the oldest and cancels prizes on the others. You can delete your account any time at kringapp.com/delete-account.html.$$,'terms §2, §7',now()),
('kb_16_account_th','th',$$หนึ่งคน หนึ่งบัญชี ถ้าพบว่ามีมากกว่าหนึ่งบัญชี กริ๊ง! จะเก็บบัญชีที่เก่าที่สุดไว้และยกเลิกรางวัลของบัญชีอื่น ลบบัญชีได้ทุกเมื่อที่ kringapp.com/delete-account.html$$,'terms §2, §7',now()),
('kb_17_contact_en','en',$$Contact: Help in the app (Talk to the team) · LINE @194hsqbc · ops@kringapp.com$$,'creator-terms contact',now()),
('kb_17_contact_th','th',$$ติดต่อ: เมนูช่วยเหลือในแอป (คุยกับทีมงาน) · LINE @194hsqbc · ops@kringapp.com$$,'creator-terms contact',now());
